from pathlib import Path
import sys

image = Path(sys.argv[1]).read_bytes()
assert image[8:12] == b"KNLT", "missing Telink RAM startup header"
assert len(image) < 0x6000, "program overlaps the mailbox"
lines = [", ".join(f"0x{x:02x}" for x in image[i:i+12]) for i in range(0, len(image), 12)]
Path(sys.argv[2]).write_text(
    "// Generated by tag-firmware/Makefile.\n#pragma once\n#include <stdint.h>\n\n"
    "static constexpr uint8_t nebularRamImage[] = {\n  " + ",\n  ".join(lines) + "\n};\n"
)
